style.css:
@-moz-document domain("github.com") {
/*
 * GitHub · 赛博终端 HUD（完全改造版）
 * 母题：HUD 网格背景 + 霓虹夜城主视觉 + 切角面板（四角括号、细霓虹描边、扫描线）+ 终端前缀标题 + 霓虹描边按钮。
 * 四色：虚空 #0d0b1f / 品红 #ff3fb4 / 青 #34e0ff / 字色 #e4ecff
 */

/* ============ 变量 ============ */
:root,
html[data-color-mode] {
  --hud-void: #0d0b1f;
  --hud-pink: #ff3fb4;
  --hud-cyan: #34e0ff;
  --hud-text: #e4ecff;
  --hud-mono: ui-monospace, "Cascadia Mono", "Cascadia Code", Consolas, "SFMono-Regular", Menlo, monospace;
  --hud-line: rgba(52, 224, 255, 0.42);
  --hud-card: rgba(13, 11, 31, 0.9);
  /* 切角：左上 + 右下 */
  --hud-clip: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px);
  --hud-clip-s: polygon(7px 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%, 0 7px);
  /* 面板图层：两条切角斜线（青）、右上 / 左下品红角括号、扫描线 */
  --hud-panel-img:
    linear-gradient(135deg, transparent 9.2px, #34e0ff 9.2px 10.6px, transparent 10.6px),
    linear-gradient(-45deg, transparent 9.2px, #34e0ff 9.2px 10.6px, transparent 10.6px),
    linear-gradient(#ff3fb4, #ff3fb4), linear-gradient(#ff3fb4, #ff3fb4),
    linear-gradient(#ff3fb4, #ff3fb4), linear-gradient(#ff3fb4, #ff3fb4),
    repeating-linear-gradient(0deg, rgba(52, 224, 255, 0.035) 0 1px, transparent 1px 4px);
  --hud-panel-pos: 0 0, 100% 100%, 100% 0, 100% 0, 0 100%, 0 100%, 0 0;
  --hud-panel-size: 20px 20px, 20px 20px, 28px 2px, 2px 28px, 28px 2px, 2px 28px, auto;

  --bgColor-default: rgba(13, 11, 31, 0.9) !important;
  --bgColor-muted: rgba(52, 224, 255, 0.05) !important;
  --bgColor-inset: rgba(6, 5, 16, 0.7) !important;
  --bgColor-emphasis: #1f1a45 !important;
  --bgColor-accent-emphasis: #ff3fb4 !important;
  --bgColor-accent-muted: rgba(52, 224, 255, 0.12) !important;
  --bgColor-neutral-muted: rgba(52, 224, 255, 0.1) !important;
  --bgColor-success-muted: rgba(57, 229, 140, 0.14) !important;
  --bgColor-done-muted: rgba(255, 63, 180, 0.14) !important;
  --fgColor-default: #e4ecff !important;
  --fgColor-muted: #9fa9cf !important;
  --fgColor-accent: #34e0ff !important;
  --fgColor-link: #34e0ff !important;
  --fgColor-success: #39e58c !important;
  --fgColor-done: #ff7ac6 !important;
  --fgColor-danger: #ff7b8a !important;
  --borderColor-default: rgba(52, 224, 255, 0.22) !important;
  --borderColor-muted: rgba(52, 224, 255, 0.14) !important;
  --borderColor-neutral-muted: rgba(52, 224, 255, 0.14) !important;
  --borderColor-translucent: rgba(52, 224, 255, 0.18) !important;
  --borderColor-emphasis: rgba(52, 224, 255, 0.5) !important;
  --borderColor-accent-emphasis: #34e0ff !important;
  --borderColor-accent-muted: rgba(52, 224, 255, 0.35) !important;
  --button-default-bgColor-rest: rgba(52, 224, 255, 0.06) !important;
  --button-default-bgColor-hover: rgba(52, 224, 255, 0.16) !important;
  --button-default-bgColor-active: rgba(52, 224, 255, 0.22) !important;
  --button-default-borderColor-rest: rgba(52, 224, 255, 0.55) !important;
  --button-default-borderColor-hover: #34e0ff !important;
  --button-default-fgColor-rest: #e4ecff !important;
  --button-default-shadow-resting: none !important;
  --button-invisible-fgColor-rest: #e4ecff !important;
  --button-invisible-iconColor-rest: #9fa9cf !important;
  --button-invisible-bgColor-hover: rgba(52, 224, 255, 0.1) !important;
  --button-primary-bgColor-rest: rgba(255, 63, 180, 0.2) !important;
  --button-primary-bgColor-hover: rgba(255, 63, 180, 0.34) !important;
  --button-primary-borderColor-rest: #ff3fb4 !important;
  --button-primary-fgColor-rest: #fff !important;
  --control-bgColor-rest: rgba(6, 5, 16, 0.7) !important;
  --control-bgColor-hover: rgba(52, 224, 255, 0.1) !important;
  --control-borderColor-rest: rgba(52, 224, 255, 0.4) !important;
  --control-fgColor-rest: #e4ecff !important;
  --control-fgColor-placeholder: #7f88b0 !important;
  --control-checked-bgColor-rest: #ff3fb4 !important;
  --underlineNav-borderColor-active: #34e0ff !important;
  --underlineNav-iconColor-rest: #9fa9cf !important;
  --overlay-bgColor: #15122f !important;
  --shadow-resting-small: none !important;
  --shadow-resting-xsmall: none !important;
  --controlTrack-bgColor-rest: rgba(6, 5, 16, 0.7) !important;
  --controlKnob-bgColor-rest: #1f1a45 !important;
  --controlKnob-borderColor-rest: #34e0ff !important;
  --color-prettylights-syntax-comment: #8b949e !important;
  --color-prettylights-syntax-constant: #79c0ff !important;
  --color-prettylights-syntax-entity: #d2a8ff !important;
  --color-prettylights-syntax-entity-tag: #7ee787 !important;
  --color-prettylights-syntax-keyword: #ff7ac6 !important;
  --color-prettylights-syntax-string: #a5d6ff !important;
  --color-prettylights-syntax-variable: #ffa657 !important;
  --color-prettylights-syntax-storage-modifier-import: #e4ecff !important;
  --color-prettylights-syntax-markup-heading: #34e0ff !important;
  /* 贡献图：霓虹矩阵 */
  --contribution-default-bgColor-0: rgba(52, 224, 255, 0.07) !important;
  --contribution-default-bgColor-1: #155e73 !important;
  --contribution-default-bgColor-2: #22b7d9 !important;
  --contribution-default-bgColor-3: #b13fd0 !important;
  --contribution-default-bgColor-4: #ff3fb4 !important;
  --contribution-default-borderColor-0: rgba(52, 224, 255, 0.12) !important;
}

/* ============ 整页：夜城 + 深色遮罩 + HUD 网格 ============ */
html {
  background: #0d0b1f !important;
}
body.page-responsive {
  background:
    linear-gradient(rgba(52, 224, 255, 0.045) 1px, transparent 1px) 0 0 / 48px 48px fixed,
    linear-gradient(90deg, rgba(52, 224, 255, 0.045) 1px, transparent 1px) 0 0 / 48px 48px fixed,
    linear-gradient(rgba(13, 11, 31, 0.78), rgba(13, 11, 31, 0.9)) fixed,
    url("data:image/webp;base64,") center top / cover fixed,
    #0d0b1f !important;
  color: #e4ecff !important;
}
body > div.logged-out,
.application-main,
.application-main main,
#js-repo-pjax-container,
.Layout,
.Layout-main,
.Layout-sidebar,
.footer,
footer {
  background: transparent !important;
}

/* ============ 顶部营销头：终端标题栏 ============ */
.js-header-wrapper [data-target="react-partial.reactRoot"] > div[data-color-mode],
header.HeaderMktg {
  background: #08071a !important;
}
header.HeaderMktg {
  border-bottom: 1px solid var(--hud-line) !important;
  box-shadow: inset 0 -2px 0 -1px rgba(255, 63, 180, 0.0), 0 1px 0 rgba(255, 63, 180, 0.35) !important;
}
header.HeaderMktg a[href*="signup"] {
  background: rgba(255, 63, 180, 0.22) !important;
  border: 1px solid #ff3fb4 !important;
  border-radius: 0 !important;
  clip-path: var(--hud-clip-s);
  font-family: var(--hud-mono) !important;
}
header.HeaderMktg a[href*="signup"],
header.HeaderMktg a[href*="signup"] * {
  color: #fff !important;
  -webkit-text-fill-color: #fff !important;
  opacity: 1 !important;
}

/* ============ 主视觉：HUD 屏幕（380px） ============ */
.application-main {
  position: relative !important;
}
/* 夜城底图 + 网格 + 左侧压暗；内容是标签行 + 大标题 */
.application-main::before {
  content: "SYS.ONLINE // NODE://GITHUB.COM // UPLINK 99.8%\A GITHUB";
  display: block;
  box-sizing: border-box;
  height: 380px;
  padding: 92px 0 0 max(56px, calc(50% - 590px));
  white-space: pre;
  font: italic 900 108px/1.02 "Segoe UI Black", "Arial Black", system-ui, sans-serif;
  letter-spacing: 0.03em;
  color: #e4ecff;
  text-shadow: -4px 0 rgba(255, 63, 180, 0.9), 4px 0 rgba(52, 224, 255, 0.9), 0 0 28px rgba(52, 224, 255, 0.45);
  background:
    linear-gradient(rgba(52, 224, 255, 0.06) 1px, transparent 1px) 0 0 / 100% 24px,
    linear-gradient(90deg, rgba(13, 11, 31, 0.92) 0%, rgba(13, 11, 31, 0.6) 38%, rgba(13, 11, 31, 0) 62%),
    linear-gradient(0deg, rgba(13, 11, 31, 0.85), rgba(13, 11, 31, 0) 30%),
    radial-gradient(circle at calc(50% + 470px) 55%, rgba(255, 63, 180, 0.32), transparent 260px),
    url("data:image/webp;base64,") center 42% / cover no-repeat;
  border-bottom: 1px solid var(--hud-line);
}
/* 第一行：等宽小标签。这里只占位（透明），文字由下面的标签层按页面绘制 */
.application-main::first-line {
  font: 600 14px/2.4 var(--hud-mono);
  letter-spacing: 0.22em;
  color: transparent;
  text-shadow: none;
}
/* 标签层：挂在 .application-main 的第一个孙元素上，绝对定位回主视觉第一行 */
.application-main > :first-child > :first-child::after {
  content: "SYS.ONLINE // NODE://GITHUB.COM // UPLINK 99.8%";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 380px;
  box-sizing: border-box;
  padding: 92px 0 0 max(56px, calc(50% - 590px));
  white-space: pre;
  font: 600 14px/2.4 var(--hud-mono);
  letter-spacing: 0.22em;
  color: #34e0ff;
  text-shadow: 0 0 8px rgba(52, 224, 255, 0.6);
  pointer-events: none;
  z-index: 0;
}
body.page-profile .application-main > :first-child > :first-child::after {
  content: "SYS.ONLINE // SCAN://USER.PROFILE // ID VERIFIED";
}
/* Trending / Explore：第一个孙元素就是 sticky 的 .site-subnav，标签层贴在它上方 380px */
body .application-main > :first-child > .site-subnav:first-child::after {
  content: "SYS.ONLINE // FEED://TRENDING // LIVE SIGNAL";
  top: auto;
  bottom: 100%;
}
/* HUD 外框：切角 + 四角括号 + 刻度尺；底部副标题 */
.application-main > :first-child::before {
  content: ">_ 代码，在霓虹夜城上线\A    NEON CODE TERMINAL // BUILD 2026.11";
  position: absolute;
  top: 16px;
  left: 16px;
  right: 16px;
  height: 348px;
  box-sizing: border-box;
  padding: 262px 0 0 calc(max(56px, 50% - 590px) - 14px);
  white-space: pre;
  font: 600 17px/1.55 var(--hud-mono);
  letter-spacing: 0.08em;
  color: #e4ecff;
  border: 1px solid var(--hud-line);
  clip-path: polygon(22px 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%, 0 22px);
  background:
    linear-gradient(135deg, transparent 15px, #34e0ff 15px 16.5px, transparent 16.5px) 0 0 / 30px 30px no-repeat border-box,
    linear-gradient(-45deg, transparent 15px, #34e0ff 15px 16.5px, transparent 16.5px) 100% 100% / 30px 30px no-repeat border-box,
    linear-gradient(#ff3fb4, #ff3fb4) 100% 0 / 46px 3px no-repeat border-box,
    linear-gradient(#ff3fb4, #ff3fb4) 100% 0 / 3px 46px no-repeat border-box,
    linear-gradient(#ff3fb4, #ff3fb4) 0 100% / 46px 3px no-repeat border-box,
    linear-gradient(#ff3fb4, #ff3fb4) 0 100% / 3px 46px no-repeat border-box,
    repeating-linear-gradient(90deg, rgba(52, 224, 255, 0.7) 0 1px, transparent 1px 12px) 60px calc(100% - 10px) / 320px 8px no-repeat,
    linear-gradient(90deg, #ff3fb4, rgba(255, 63, 180, 0)) max(42px, calc(50% - 604px)) 236px / 260px 2px no-repeat;
  pointer-events: none;
  z-index: 1;
}
/* 唯一环境动效：一条扫描线缓慢扫过主视觉 */
.application-main > :first-child::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 380px;
  background: linear-gradient(180deg, transparent, rgba(52, 224, 255, 0.07) 80%, rgba(52, 224, 255, 0.35) 98%, transparent) 0 -90px / 100% 90px no-repeat;
  animation: hud-sweep 7s linear infinite;
  pointer-events: none;
  z-index: 3;
}
@keyframes hud-sweep {
  to { background-position: 0 470px; }
}
/* 大尺寸看板娘：站在右侧，下沿被主视觉底边裁切 */
.application-main::after {
  content: "";
  position: absolute;
  top: 22px;
  right: max(72px, calc(50% - 560px));
  width: 261px;
  height: 560px;
  background: url("data:image/webp;base64,") center top / contain no-repeat;
  filter: drop-shadow(0 0 1px #34e0ff) drop-shadow(0 0 14px rgba(255, 63, 180, 0.55));
  clip-path: inset(-20px -40px 202px -40px);
  pointer-events: none;
  z-index: 2;
}

/* ============ 仓库头 / 子导航：HUD 工具条 ============ */
header.GlobalNav,
.AppHeader,
.site-subnav,
.UnderlineNav,
.page-profile main > .position-sticky {
  background: rgba(8, 7, 26, 0.94) !important;
  box-shadow: inset 0 -1px 0 var(--hud-line) !important;
}
.page-profile main > .position-sticky.tmp-mt-4 {
  margin-top: 0 !important;
}
header.GlobalNav [class*="contextCrumb"],
header.GlobalNav [class*="ContextCrumb"],
header.GlobalNav a[href$="/vscode"],
header.GlobalNav li a {
  font-family: var(--hud-mono) !important;
  letter-spacing: 0.04em;
}
/* 标签页：HUD 开关 */
nav[class*="UnderlineWrapper"] a,
.UnderlineNav-item,
.site-subnav a,
.subnav-item {
  font-family: var(--hud-mono) !important;
  font-size: 13px !important;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
nav[class*="UnderlineWrapper"] a[aria-current="page"],
.UnderlineNav-item.selected,
.UnderlineNav-item[aria-current]:not([aria-current="false"]),
.site-subnav a.selected {
  color: #34e0ff !important;
  background: linear-gradient(0deg, rgba(52, 224, 255, 0.16), rgba(52, 224, 255, 0.02)) !important;
  border-bottom-color: #34e0ff !important;
  text-shadow: 0 0 10px rgba(52, 224, 255, 0.6);
  clip-path: var(--hud-clip-s);
}
.subnav-item {
  border-color: var(--hud-line) !important;
  border-radius: 0 !important;
  background: transparent !important;
}
.subnav-item.selected,
.subnav-item[aria-current="page"] {
  background: rgba(255, 63, 180, 0.2) !important;
  border-color: #ff3fb4 !important;
  color: #fff !important;
}

/* ============ HUD 面板 ============ */
.Box:not(.Popover-message),
[data-testid="directory-content"] > table,
[data-component="SplitPageLayout.Content"] div[data-hpc] + div > div:only-child,
[class*="blobContentSection"],
[class*="borderGrid__"],
li.position-relative[class*="container__"],
[id$="-list-view-container"],
.js-yearly-contributions .border {
  background-color: var(--hud-card) !important;
  background-image: var(--hud-panel-img) !important;
  background-position: var(--hud-panel-pos) !important;
  background-size: var(--hud-panel-size) !important;
  background-repeat: no-repeat, no-repeat, no-repeat, no-repeat, no-repeat, no-repeat, repeat !important;
  background-origin: border-box !important;
  border: 1px solid var(--hud-line) !important;
  border-radius: 0 !important;
  box-shadow: inset 0 0 30px rgba(52, 224, 255, 0.05) !important;
  clip-path: var(--hud-clip);
}
[class*="borderGrid__"] {
  padding: 0 18px !important;
}
/* 面板里的嵌套块：不叠底、不再切角 */
.Box .Box,
.Box .Box-row,
.Box-header,
.Box-footer,
div[itemtype="https://schema.org/abstract"],
[class*="borderGrid__"] [class*="borderGrid__"],
[class*="borderGrid__"] [class*="sidebarSection"] {
  background-color: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
  clip-path: none;
}
.Box-header {
  border-color: var(--hud-line) !important;
  border-style: dashed !important;
}
/* 提交状态条：终端状态行 */
.bgColor-muted.rounded-top-2,
[class*="contentWrapper"] > .border.rounded-2,
[class*="legacyDensityToggle"],
[id$="-list-view-metadata"] > [class*="primerActionBar"],
#repos-sticky-header [data-testid="screen-reader-heading"] + div {
  background: linear-gradient(90deg, rgba(255, 63, 180, 0.14), rgba(52, 224, 255, 0.06)) !important;
  border: 1px solid var(--hud-line) !important;
  border-radius: 0 !important;
  font-family: var(--hud-mono);
  font-size: 13px;
  clip-path: polygon(14px 0, 100% 0, 100% 100%, 0 100%, 0 14px);
}

/* ============ 终端前缀标题 ============ */
h2[class*="sectionHeading"],
.page-profile main h2.f4,
.page-profile main h2.h4,
.page-profile main h3.f5,
h1[class*="title__"],
h2[class*="heading__"],
main .container-lg > h1.h1 {
  font-family: var(--hud-mono) !important;
  font-weight: 700 !important;
  letter-spacing: 0.08em !important;
  text-transform: uppercase;
  color: #e4ecff !important;
}
h2[class*="sectionHeading"]::before,
.page-profile main h2.f4::before,
.page-profile main h2.h4::before,
.page-profile main h3.f5::before,
h1[class*="title__"]::before,
h2[class*="heading__"]::before,
main .container-lg > h1.h1::before {
  content: ">_ ";
  color: #34e0ff;
  text-shadow: 0 0 8px rgba(52, 224, 255, 0.7);
}
.page-profile main h2.f4 {
  font-size: 15px !important;
}
/* Trending 标题块压成一条终端行 */
main > .color-bg-subtle.border-bottom {
  background: transparent !important;
  border-color: var(--hud-line) !important;
}
main > .color-bg-subtle.border-bottom > .container-lg {
  padding-top: 18px !important;
  padding-bottom: 18px !important;
  text-align: left !important;
  display: flex;
  align-items: baseline;
  gap: 18px;
}
main .container-lg > h1.h1 {
  font-size: 24px !important;
}
main > .color-bg-subtle.border-bottom p {
  font-family: var(--hud-mono);
  font-size: 13px !important;
  color: #9fa9cf !important;
  margin: 0 !important;
}

/* ============ 文件列表：终端输出 ============ */
[data-testid="directory-content"] table,
[class*="react-directory-row"] {
  font-family: var(--hud-mono) !important;
  font-size: 13px !important;
}
[data-testid="directory-content"] tbody tr {
  transition: background-color 0.15s ease, box-shadow 0.15s ease;
}
[data-testid="directory-content"] tbody tr:hover {
  background-color: rgba(52, 224, 255, 0.07) !important;
  box-shadow: inset 3px 0 0 #34e0ff;
}
[data-testid="directory-content"] .icon-directory,
[data-testid="directory-content"] svg[class*="icon-directory"] {
  fill: #34e0ff !important;
  color: #34e0ff !important;
}

/* 文件页左侧文件树：终端侧栏 */
#repos-file-tree {
  background: rgba(8, 7, 26, 0.9) !important;
  box-shadow: inset -1px 0 0 var(--hud-line) !important;
}
#repos-file-tree [role="treeitem"] {
  font-family: var(--hud-mono) !important;
  font-size: 13px !important;
}
/* 分段切换：HUD 开关 */
ul[class*="SegmentedControl-SegmentedControl"] {
  background: rgba(6, 5, 16, 0.7) !important;
  border: 1px solid var(--hud-line) !important;
  border-radius: 0 !important;
}
ul[class*="SegmentedControl-SegmentedControl"] button {
  border-radius: 0 !important;
  font-family: var(--hud-mono) !important;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
ul[class*="SegmentedControl-SegmentedControl"]::before,
li[class*="SegmentedControl-Item"][data-selected] button,
button[aria-current="true"][class*="SegmentedControl-Button"] {
  background: rgba(52, 224, 255, 0.18) !important;
  color: #34e0ff !important;
  border-radius: 0 !important;
}
.react-blob-sticky-header > div,
[class*="_stickied"] {
  background-color: rgba(8, 7, 26, 0.97) !important;
}

/* ============ Issues：日志行 ============ */
li[class*="unreadBorder"]::before {
  background: transparent !important;
}
[id$="-list-view-container"] li[class*="ListItem"]:hover,
[id$="-list-view-container"] [role="listitem"]:hover {
  background-color: rgba(52, 224, 255, 0.06) !important;
  box-shadow: inset 3px 0 0 #ff3fb4;
}
[id$="-list-view-container"] [class*="description"],
[id$="-list-view-container"] [class*="Description"] {
  font-family: var(--hud-mono);
  font-size: 12px !important;
}
/* 左侧导航：选中项一根青色光条 */
[class*="prc-ActionList-ActionListItem"][aria-current]:not([aria-current="false"]),
[data-component="NavList"] [class*="prc-ActionList-ActionListItem"][data-active="true"] {
  background: rgba(52, 224, 255, 0.1) !important;
  border-radius: 0 !important;
}
[class*="prc-ActionList-ActionListItem"] [class*="ActiveIndicator"],
[class*="prc-ActionList-ActionListItem"]::after {
  background: #34e0ff !important;
  border-radius: 0 !important;
}
/* 搜索框：切角输入槽 */
[class*="prc-TextInput-TextInputBaseWrapper"],
[class*="prc-TextInput-TextInputWrapper"],
.form-control {
  border-radius: 0 !important;
  border-color: var(--hud-line) !important;
  clip-path: var(--hud-clip-s);
  font-family: var(--hud-mono) !important;
}

/* ============ Trending：编号情报卡 ============ */
.Box > div {
  counter-reset: hud-rank;
}
article.Box-row {
  position: relative;
  counter-increment: hud-rank;
  padding-left: 72px !important;
  border-top: 1px dashed rgba(52, 224, 255, 0.22) !important;
  transition: background-color 0.15s ease, box-shadow 0.15s ease;
}
article.Box-row::before {
  content: counter(hud-rank, decimal-leading-zero);
  position: absolute;
  left: 20px;
  top: 16px;
  font: 700 22px/1 var(--hud-mono);
  color: #34e0ff;
  text-shadow: 0 0 10px rgba(52, 224, 255, 0.6);
}
article.Box-row:nth-child(-n + 3)::before {
  color: #ff3fb4;
  text-shadow: 0 0 10px rgba(255, 63, 180, 0.7);
}
article.Box-row:hover {
  background-color: rgba(52, 224, 255, 0.05) !important;
  box-shadow: inset 3px 0 0 #ff3fb4 !important;
}
article.Box-row h2 a,
.pinned-item-list-item .repo,
.pinned-item-list-item a.Link {
  font-family: var(--hud-mono) !important;
  letter-spacing: 0.02em;
}

/* ============ 个人主页 ============ */
/* 头像：八角 HUD 取景框 */
.page-profile .js-profile-editable-area img.avatar-user,
.page-profile img.avatar-user.avatar.width-full {
  border-radius: 0 !important;
  padding: 4px !important;
  box-sizing: border-box !important;
  background: linear-gradient(135deg, #34e0ff, #ff3fb4) !important;
  box-shadow: none !important;
  clip-path: polygon(18% 0, 82% 0, 100% 18%, 100% 82%, 82% 100%, 18% 100%, 0 82%, 0 18%);
}
.vcard-names .p-name {
  font-family: var(--hud-mono) !important;
  font-weight: 700 !important;
  text-shadow: -1px 0 rgba(255, 63, 180, 0.8), 1px 0 rgba(52, 224, 255, 0.8);
}
.vcard-names .p-nickname {
  font-family: var(--hud-mono) !important;
  color: #34e0ff !important;
}
.vcard-names .p-nickname::before {
  content: "@";
}
.pinned-item-list-item .Box {
  transition: transform 0.18s ease, background-color 0.18s ease !important;
}
.pinned-item-list-item .Box:hover {
  transform: translate(-2px, -2px);
  background-color: rgba(31, 26, 69, 0.95) !important;
}
/* 贡献图：霓虹矩阵 */
.ContributionCalendar-day {
  border-radius: 1px !important;
}
.ContributionCalendar-day[data-level="3"] {
  box-shadow: 0 0 5px rgba(177, 63, 208, 0.8);
}
.ContributionCalendar-day[data-level="4"] {
  box-shadow: 0 0 7px rgba(255, 63, 180, 0.95);
}
.ContributionCalendar-label {
  font-family: var(--hud-mono);
  fill: #34e0ff !important;
  color: #34e0ff !important;
}
a.js-year-link {
  border-radius: 0 !important;
  font-family: var(--hud-mono);
}
a.js-year-link.selected {
  background: rgba(255, 63, 180, 0.18) !important;
  box-shadow: inset 3px 0 0 #ff3fb4 !important;
  color: #fff !important;
}

/* ============ 代码与 README ============ */
.markdown-body pre,
.markdown-body .highlight pre {
  background: #07061a !important;
  border: 1px solid rgba(52, 224, 255, 0.25) !important;
  border-left: 3px solid #34e0ff !important;
  border-radius: 0 !important;
}
.markdown-body code {
  background: rgba(52, 224, 255, 0.12) !important;
  color: #c8f6ff !important;
  border-radius: 0 !important;
}
.markdown-body pre code {
  background: transparent !important;
  color: inherit !important;
}
.markdown-body h1,
.markdown-body h2 {
  border-bottom: 1px dashed rgba(52, 224, 255, 0.3) !important;
}
.markdown-body table tr,
.markdown-body table td,
.markdown-body table th {
  background: transparent !important;
}

/* ============ 按钮、计数、标签：霓虹描边芯片 ============ */
.btn,
[class*="prc-Button-ButtonBase"]:not([data-variant="invisible"]) {
  border-radius: 0 !important;
  clip-path: var(--hud-clip-s);
  font-family: var(--hud-mono) !important;
  letter-spacing: 0.03em;
}
.btn-primary,
[data-variant="primary"] {
  background: rgba(255, 63, 180, 0.2) !important;
  border: 1px solid #ff3fb4 !important;
  color: #fff !important;
  text-shadow: 0 0 8px rgba(255, 63, 180, 0.8);
}
.btn:hover,
[class*="prc-Button-ButtonBase"]:hover {
  box-shadow: inset 0 0 12px rgba(52, 224, 255, 0.35) !important;
}
.Counter,
[class*="prc-CounterLabel"] {
  border-radius: 0 !important;
  background: transparent !important;
  border: 1px solid rgba(52, 224, 255, 0.45) !important;
  color: #34e0ff !important;
  font-family: var(--hud-mono);
}
.topic-tag,
a.topic-tag {
  background: rgba(255, 63, 180, 0.1) !important;
  border: 1px solid rgba(255, 63, 180, 0.6) !important;
  border-radius: 0 !important;
  color: #ff9ad3 !important;
  font-family: var(--hud-mono);
  clip-path: var(--hud-clip-s);
}
.topic-tag::before {
  content: "#";
  opacity: 0.7;
}
.topic-tag:hover {
  background: rgba(255, 63, 180, 0.3) !important;
  color: #fff !important;
}
[class*="IssueLabel"],
.Label,
.IssueLabel,
[class*="borderGrid__"] a[href*="/topics/"] {
  border-radius: 0 !important;
  font-family: var(--hud-mono);
}
[class*="borderGrid__"] a[href*="/topics/"] {
  background: rgba(255, 63, 180, 0.1) !important;
  border: 1px solid rgba(255, 63, 180, 0.6) !important;
  color: #ff9ad3 !important;
  clip-path: var(--hud-clip-s);
}
/* Issue 标签：统一成青色描边芯片，不再是彩色色块 */
[id$="-list-view-container"] [class*="IssueLabel"] {
  background: rgba(52, 224, 255, 0.08) !important;
  border: 1px solid rgba(52, 224, 255, 0.55) !important;
  color: #9ff0ff !important;
  box-shadow: none !important;
}
[id$="-list-view-container"] [class*="IssueLabel"] * {
  color: #9ff0ff !important;
}
a:hover {
  color: #ff7ac6 !important;
}

/* ============ 页脚 ============ */
.footer {
  border-top: 1px solid var(--hud-line) !important;
  font-family: var(--hud-mono);
}

/* ============ 选中色、滚动条 ============ */
::selection { background: rgba(255, 63, 180, 0.4); color: #fff; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: #0d0b1f; }
::-webkit-scrollbar-thumb { background: #1f3a55; border: 2px solid #0d0b1f; }
::-webkit-scrollbar-thumb:hover { background: #34e0ff; }
}
